/* Nội dung cập nhật có chọn lọc 16/10/2026. Giữ ID theo kỹ năng để giữ tiến độ. */
window.LESSON = {"id":"bai02","number":2,"title":"Biến và lệnh cin","story":"Em làm chủ cửa hàng nước","badge":{"icon":"🧮","name":"Thu ngân căng tin"},"skills":["Khai báo và chọn kiểu dữ liệu phù hợp","Nhập số ly, tính tiền và in hóa đơn"],"errorTable":[["Máy chưa biết tên biến","Chưa khai báo hoặc gõ khác hoa/thường","Khai báo trước rồi dùng đúng tên."],["Dữ liệu nhập chưa hợp lệ","Bài yêu cầu số nguyên không âm","Nhập đúng số lượng và số giá trị ghi trong đề."],["Kết quả chưa khớp","Phép tính, điều kiện hoặc số lượt chưa đúng","Đối chiếu từng test case; thử đúng mốc trong đề."]],"steps":[{"kind":"stage","id":"stage-1","number":1,"nav":"Khai báo","kicker":"CHẶNG 1","title":"Khai báo","bit":"Em là chủ cửa hàng nước. Bit giúp em đọc yêu cầu, xem ví dụ rồi tự hoàn thiện chương trình.","objectives":["Nhận biết tên, kiểu và giá trị","Khai báo biến với kiểu phù hợp"],"lesson":"<div class="note-card blue"><h3>Việc của chủ cửa hàng</h3><p>Em mở quầy trà đào, giá 10.000 đồng một ly. Chương trình cần nhớ giá bán và số ly.</p></div><p>Khai báo tạo biến. Khởi tạo đặt giá trị ban đầu. Sau đó gán lại mà không viết kiểu lần nữa. Biến cục bộ chưa được khởi tạo hoặc nhập dữ liệu thì chưa có giá trị xác định để tính hay in.</p><div class="pair-view"><div class="code-demo"><div class="code-demo-header">Ví dụ đã làm</div><pre><code>int giaLy = 10000;
int soLy = 3;
cout &lt;&lt; soLy;</code></pre></div><div class="screen-card"><div class="screen-head">KẾT QUẢ</div><pre>3</pre></div></div><div class="note-card blue"><h3>Đến lượt em</h3><p>Khai báo biến soLy rồi in giá trị của biến.</p></div><div class="note-card blue"><h3>Mỗi biến có tên, kiểu và giá trị</h3><p>Biến giúp chương trình lưu một giá trị để dùng tiếp. Kiểu dữ liệu cho biết loại giá trị biến lưu. Ví dụ <code>int soLy = 3;</code>: <code>int</code> là kiểu, <code>soLy</code> là tên, <code>3</code> là giá trị ban đầu; dấu <code>;</code> kết thúc lệnh.</p></div><div style="overflow-x:auto"><table class="tb-table"><thead><tr><th>Thông tin</th><th>Kiểu</th><th>Ví dụ khai báo</th></tr></thead><tbody><tr><td>Số ly (số nguyên)</td><td><code>int</code></td><td><code>int soLy = 3;</code></td></tr><tr><td>Dung tích, đơn vị lít (số thực)</td><td><code>double</code></td><td><code>double dungTich = 0.5;</code></td></tr><tr><td>Một ký tự tiếng Anh</td><td><code>char</code></td><td><code>char kichCo = 'M';</code></td></tr><tr><td>Đúng hoặc sai</td><td><code>bool</code></td><td><code>bool conHang = true;</code></td></tr><tr><td>Văn bản</td><td><code>string</code></td><td><code>string tenMon = "Tra dao";</code></td></tr></tbody></table></div><p><code>char</code> dùng nháy đơn; <code>string</code> dùng nháy kép và cần <code>#include &lt;string&gt;</code> với <code>using namespace std;</code>. Trình chạy gọn trên web chưa hỗ trợ thư viện string; thử ví dụ văn bản trên Programiz. <code>bool</code> có giá trị true/false, cout mặc định in 1/0.</p><p><code>float</code> cũng lưu số thực nhưng thường có độ chính xác thấp hơn double. Bài này dùng double, ví dụ <code>double dungTich = 0.5;</code>. Viết dấu chấm trong số thập phân.</p><div class="note-card blue"><h3>Tên biến dễ hiểu</h3><p>Dùng tên như giaLy, soLy: chữ cái tiếng Anh, chữ số và dấu _. Không bắt đầu bằng số, không có dấu cách, không trùng từ khóa. Tên phân biệt hoa/thường. Trong cùng khối, mỗi biến chỉ khai báo một lần.</p></div>","challenges":[{"id":"s1-predict","type":"choice","icon":"🔎","title":"Đọc ví dụ: Biến hay chữ?","prompt":"Dòng nào in giá trị 3?","code":"int soLy = 3;","options":[{"text":"cout << "soLy";","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"cout << soLy;"}],"answer":"cout << soLy;","why":"Không có nháy kép thì cout đọc giá trị của biến. Nháy kép in nguyên văn chữ."},{"id":"s1-code","type":"code","icon":"⌨️","title":"Đến lượt em: Nhớ số ly","prompt":"Khách đầu tiên mua 3 ly. Điền khai báo để soLy giữ số 3. Dòng in đã có sẵn.","starter":"#include <iostream>
using namespace std;

int main() {
    // Dien khai bao soLy o day
    cout << soLy;
    return 0;
}
","tests":[{"input":"","expected":"3","pureExpected":"3"}],"inputSpec":{"min":0},"requirements":["Khai báo soLy kiểu int và khởi tạo bằng 3."],"hints":["Mẫu: kiểu tên = giá trị;","int soLy = 3;"],"why":"Kết quả khớp các test case. Hãy giải thích dòng lệnh em vừa hoàn thiện.","rules":[{"test":(function anonymous(code
) {
return new RegExp("int\s+soLy\s*=\s*3").test(window.CPP.stripComments(code));
}),"msg":"Hãy khai báo int soLy = 3; trước dòng in."},{"test":(function anonymous(code
) {
return new RegExp("<<\s*soLy\b").test(window.CPP.stripComments(code));
}),"msg":"Dùng biến soLy trong dòng cout."}]},{"id":"s2-name","type":"choice","icon":"🔎","title":"Thử thêm: Đặt tên","prompt":"Tên nào phù hợp để lưu số ly?","options":[{"text":"2ly","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"so ly","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"soLy"}],"answer":"soLy","why":"soLy bắt đầu bằng chữ, không có khoảng trắng và nêu rõ ý nghĩa.","bonus":true},{"id":"shop-types","type":"choice","icon":"🔎","title":"Thử thêm: Chọn kiểu","prompt":"Dung tích một ly là 0.5 lít. Chọn khai báo giữ được phần thập phân.","options":[{"text":"int dungTich = 0.5;","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"double dungTich = 0.5;"}],"answer":"double dungTich = 0.5;","why":"double giữ số có phần thập phân. int dungTich = 0.5; sẽ nhận 0.","bonus":true}]},{"kind":"stage","id":"stage-2","number":2,"nav":"Nhập dữ liệu","kicker":"CHẶNG 2","title":"Nhập dữ liệu","bit":"Em là chủ cửa hàng nước. Bit giúp em đọc yêu cầu, xem ví dụ rồi tự hoàn thiện chương trình.","objectives":["Dùng cin đọc vào biến đã khai báo","Phân biệt khai báo và dữ liệu nhập"],"lesson":"<div class="note-card blue"><h3>Việc của chủ cửa hàng</h3><p>Mỗi khách mua số ly khác nhau. Em muốn nhập số lượng thay vì sửa mã cho từng khách.</p></div><p>Khai báo trước, sau đó dùng cin >> tên biến. Chương trình dưới đây dùng số nguyên. Khi nhập, chỉ gõ số, ví dụ 3; không gõ dấu nháy.</p><div class="pair-view"><div class="code-demo"><div class="code-demo-header">Ví dụ đã làm</div><pre><code>int soLy;
cin &gt;&gt; soLy;
cout &lt;&lt; soLy;</code></pre></div><div class="screen-card"><div class="screen-head">KẾT QUẢ</div><pre>Nhập 3 → in 3</pre></div></div><div class="note-card blue"><h3>Đến lượt em</h3><p>Điền dòng cin để chương trình nhận số ly của khách.</p></div><div class="note-card blue"><h3>Nhập theo kiểu của biến</h3><p><code>double dungTich; cin &gt;&gt; dungTich;</code>: gõ 0.5. <code>char kichCo; cin &gt;&gt; kichCo;</code>: gõ M. <code>bool conHang; cin &gt;&gt; conHang;</code>: mặc định gõ 1 hoặc 0. Trên Programiz, <code>cin &gt;&gt; tenMon;</code> với string chỉ đọc một từ; đọc cả dòng sẽ học sau. Các nhiệm vụ chính dưới đây yêu cầu số nguyên không âm.</p></div>","challenges":[{"id":"s3-predict","type":"choice","icon":"🔎","title":"Đọc ví dụ: Khách nhập 4","prompt":"Chương trình in số nào sau khi khách nhập 4?","code":"int soLy;
cin >> soLy;
cout << soLy;","options":[{"text":"0","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."},{"text":"4"},{"text":"soLy","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."}],"answer":"4","why":"cin lưu số 4 vào soLy; cout in giá trị vừa nhập."},{"id":"s3-code","type":"code","icon":"⌨️","title":"Đến lượt em: Nhận số ly","prompt":"Điền một dòng cin. Các dòng khai báo và in đã có sẵn. Nhập số nguyên không âm.","starter":"#include <iostream>
using namespace std;

int main() {
    int soLy;
    // Dien lenh nhap soLy
    cout << soLy;
    return 0;
}
","tests":[{"input":"3","expected":"3
3","pureExpected":"3"},{"input":"0","expected":"0
