) {
return new RegExp("giaLy\s*\*\s*soLy|soLy\s*\*\s*giaLy").test(window.CPP.stripComments(code));
}),"msg":"Hãy tính bằng hai biến giaLy và soLy."}]}]},{"kind":"stage","id":"stage-4","number":4,"nav":"Xuất kết quả","kicker":"CHẶNG 4","title":"Xuất kết quả","bit":"Em là chủ cửa hàng nước. Bit giúp em đọc yêu cầu, xem ví dụ rồi tự hoàn thiện chương trình.","objectives":["Ghép chữ với giá trị bằng cout","Hoàn thiện hóa đơn một món"],"lesson":"<div class="note-card blue"><h3>Việc của chủ cửa hàng</h3><p>Em cần đưa cho khách một hóa đơn dễ đọc.</p></div><p>Chữ đặt trong nháy kép, tên biến ở ngoài nháy kép. Dùng endl để xuống dòng. Câu dẫn trước cin giúp người dùng biết cần nhập gì; trong bài có mã khung, câu dẫn được cho sẵn.</p><div class="pair-view"><div class="code-demo"><div class="code-demo-header">Ví dụ đã làm</div><pre><code>cout &lt;&lt; "So ly: " &lt;&lt; soLy &lt;&lt; endl;
cout &lt;&lt; "Thanh tien: " &lt;&lt; thanhTien;</code></pre></div><div class="screen-card"><div class="screen-head">KẾT QUẢ</div><pre>So ly: 3
Thanh tien: 30000</pre></div></div><div class="note-card blue"><h3>Đến lượt em</h3><p>Giữ phần nhập và tính, hoàn thiện hai dòng in hóa đơn.</p></div>","challenges":[{"id":"s4-order","type":"choice","icon":"🔎","title":"Đọc ví dụ: Thứ tự xử lý","prompt":"Sau khi khai báo, thứ tự nào phù hợp để lập hóa đơn?","options":[{"text":"Nhập số ly → tính thành tiền → in hóa đơn"},{"text":"In thành tiền → nhập số ly → tính","why":"Đọc lại ví dụ và đối chiếu dữ liệu với quy tắc trong đề."}],"answer":"Nhập số ly → tính thành tiền → in hóa đơn","why":"Cần có dữ liệu trước khi tính và có kết quả trước khi in."},{"id":"s4-code","type":"code","icon":"⌨️","title":"Đến lượt em: In hóa đơn","prompt":"Điền hai tên biến trong dòng cout. Mẫu chữ đã có sẵn trong mã khung.","starter":"#include <iostream>
using namespace std;

int main() {
    int soLy;
    cin >> soLy;
    int thanhTien = 10000 * soLy;
    cout << "So ly: " << 0 << endl; // Thay 0 bang bien
    cout << "Thanh tien: " << 0;
    return 0;
}
